def ph(text):
    out=[]
    for part in re.split(r'(\{[^}]+\})',text):
        if not part:continue
        if part.startswith('{'):
            w=part[1:-1];out.append(OVR.get(w) or T.phonemize(w,'hi').strip().replace('ɟ','ʤ').replace('c','ʧ'))
        else:
            p=part.strip()
            if not p:continue
            if out and p[:1]=='s' and (len(p)==1 or not p[1].isalpha()) and part is not None and not p[:2] in ("'s","’s"):
                out[-1]+='z';p=p[1:].strip()
                if not p:continue
            if p[:2] in ("'s","’s") and out:
                out[-1]+=('s' if out[-1][-1:] in 'ptkfθ' else 'z');p=p[2:].strip()
                if not p:continue
            if p[0] in '.,;:!?':
                if out:out[-1]+=p[0]
                p=p[1:].strip()
            if p:out.append(T.phonemize(p,'en-us').strip())
    return ' '.join(out)
